class Solution {
public:
    vector<int> getFinalState(vector<int>& nums, int k, int multiplier) {
        if (multiplier == 1 || k == 0) return nums;
        const int mod = 1e9 + 7;
        int n = nums.size();
        int mx = 0;
        for (int x : nums) mx = max(mx, x);

        priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
        for (int i = 0; i < n; ++i) pq.push({nums[i], i});

        while (k > 0 && pq.top().first * multiplier <= mx) {
            auto [val, idx] = pq.top();
            pq.pop();
            pq.push({val * multiplier, idx});
            k--;
        }

        while (k > 0 && pq.top().first < mx) {
            auto [val, idx] = pq.top();
            pq.pop();
            pq.push({val * multiplier, idx});
            k--;
        }

        auto power = [&](long long base, long long exp) -> long long {
            long long res = 1;
            base %= mod;
            while (exp > 0) {
                if (exp % 2 == 1) res = (res * base) % mod;
                base = (base * base) % mod;
                exp /= 2;
            }
            return res;
        };

        long long full = k / n;
        int rem = k % n;

        long long mult_full = power(multiplier, full);
        long long mult_extra = (mult_full * multiplier) % mod;

        vector<pair<long long, int>> sorted_elems;
        while (!pq.empty()) {
            sorted_elems.push_back(pq.top());
            pq.pop();
        }

        vector<int> res(n);
        for (int i = 0; i < n; ++i) {
            long long factor = (i < rem) ? mult_extra : mult_full;
            res[sorted_elems[i].second] = (sorted_elems[i].first % mod * factor) % mod;
        }
        return res;
    }
};

class Solution {
    public int[] getFinalState(int[] nums, int k, int multiplier) {
        if (multiplier == 1 || k == 0) return nums.clone();
        int mod = 1_000_000_007;
        int n = nums.length;
        int mx = 0;
        for (int x : nums) mx = Math.max(mx, x);

        PriorityQueue<long[]> pq = new PriorityQueue<>((a, b) -> {
            if (a[0] != b[0]) return Long.compare(a[0], b[0]);
            return Long.compare(a[1], b[1]);
        });
        for (int i = 0; i < n; ++i) pq.offer(new long[]{nums[i], i});

        while (k > 0 && pq.peek()[0] * multiplier <= mx) {
            long[] top = pq.poll();
            top[0] *= multiplier;
            pq.offer(top);
            k--;
        }

        while (k > 0 && pq.peek()[0] < mx) {
            long[] top = pq.poll();
            top[0] *= multiplier;
            pq.offer(top);
            k--;
        }

        long full = k / n;
        int rem = k % n;

        long multFull = power(multiplier, full, mod);
        long multExtra = (multFull * multiplier) % mod;

        List<long[]> sorted = new ArrayList<>();
        while (!pq.isEmpty()) sorted.add(pq.poll());

        int[] res = new int[n];
        for (int i = 0; i < n; ++i) {
            long factor = (i < rem) ? multExtra : multFull;
            res[(int) sorted.get(i)[1]] = (int) ((sorted.get(i)[0] % mod * factor) % mod);
        }
        return res;
    }

    private long power(long base, long exp, int mod) {
        long res = 1;
        base %= mod;
        while (exp > 0) {
            if (exp % 2 == 1) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2;
        }
        return res;
    }
}

var getFinalState = function(nums, k, multiplier) {
    if (multiplier === 1 || k === 0) return [...nums];
    const mod = 1000000007n;
    const n = nums.length;
    let mx = Math.max(...nums);

    const power = (base, exp) => {
        let res = 1n;
        base = BigInt(base) % mod;
        exp = BigInt(exp);
        while (exp > 0n) {
            if (exp % 2n === 1n) res = (res * base) % mod;
            base = (base * base) % mod;
            exp /= 2n;
        }
        return res;
    };

    // Simulate until values converge near mx
    const arr = nums.map((v, i) => [BigInt(v), i]);
    while (k > 0) {
        let minIdx = 0;
        for (let i = 1; i < n; i++) {
            if (arr[i][0] < arr[minIdx][0] || (arr[i][0] === arr[minIdx][0] && arr[i][1] < arr[minIdx][1])) {
                minIdx = i;
            }
        }
        if (arr[minIdx][0] * BigInt(multiplier) > BigInt(mx) && arr.every(x => x[0] >= BigInt(mx) / BigInt(multiplier))) {
            break;
        }
        arr[minIdx][0] *= BigInt(multiplier);
        k--;
    }

    arr.sort((a, b) => (a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : a[1] - b[1]));
    const full = Math.floor(k / n);
    const rem = k % n;

    const multFull = power(multiplier, full);
    const multExtra = (multFull * BigInt(multiplier)) % mod;

    const res = new Array(n);
    for (let i = 0; i < n; i++) {
        const factor = (i < rem) ? multExtra : multFull;
        res[arr[i][1]] = Number(((arr[i][0] % mod) * factor) % mod);
    }
    return res;
};
